import{_ as A,H as E,o,c as p,aN as e,q as a,s as r,a as s,l,aT as i}from"./chunks/framework.D31DlcCL.js";const h=JSON.parse('{"title":"AI大模型修仙传（四）：Transformer上篇——“Attention Is All You Need”到底有多神？","description":"2017年谷歌的一篇论文如何让AI界直接“渡劫飞升”？白话解析自注意力机制与QKV矩阵，文科生也能看懂的硬核科普！","frontmatter":{"title":"AI大模型修仙传（四）：Transformer上篇——“Attention Is All You Need”到底有多神？","date":"2026-04-01T00:00:00.000Z","categories":["AI"],"tags":["大模型","Transformer","人工智能","深度学习"],"description":"2017年谷歌的一篇论文如何让AI界直接“渡劫飞升”？白话解析自注意力机制与QKV矩阵，文科生也能看懂的硬核科普！"},"headers":[],"relativePath":"posts/ai-series-4-transformer-attention.md","filePath":"posts/ai-series-4-transformer-attention.md","lastUpdated":null}'),g={name:"posts/ai-series-4-transformer-attention.md"};function d(m,t,f,B,u,T){const n=E("Mermaid");return o(),p("div",null,[t[3]||(t[3]=e('<h1 id="ai大模型修仙传-四-transformer上篇——-attention-is-all-you-need-到底有多神" tabindex="-1">AI大模型修仙传（四）：Transformer上篇——“Attention Is All You Need”到底有多神？ <a class="header-anchor" href="#ai大模型修仙传-四-transformer上篇——-attention-is-all-you-need-到底有多神" aria-label="Permalink to &quot;AI大模型修仙传（四）：Transformer上篇——“Attention Is All You Need”到底有多神？&quot;">​</a></h1><blockquote><p><strong>💡 博主导读</strong>：毫不夸张地说，Transformer是当前所有大模型的“火种”。作为技术博主，我必须用最直观的图表，带你跨过这道AI修仙路上的最大门槛！</p></blockquote><p>如果把今天的人工智能发展史写成一本修仙小说，那2017年绝对是整个修仙界“灵气复苏”的元年。</p><p>就在那一年，谷歌（Google）的八位大神在顶级会议NeurIPS上扔下了一本只有十页的“绝世秘籍”。这本秘籍的名字极度嚣张，充满了“在座的各位都是垃圾”的既视感：</p><p><strong>《Attention Is All You Need》（注意力机制就是你需要的一切）</strong></p><p>当时谁也没想到，这篇论文里提出的 <strong>Transformer</strong> 架构，会在接下来的几年里横扫千军，不仅直接催生了后来的GPT系列（Generative Pre-trained Transformer，没错，GPT里的T就是它），更是一手缔造了今天的大模型狂欢。</p><p>今天，我们就来扒一扒这本绝世秘籍的底裤，看看它到底凭什么能让AI界直接渡劫飞升。</p><hr><h3 id="一、-天下苦rnn久矣-传统门派的死局" tabindex="-1">一、 天下苦RNN久矣：传统门派的死局 <a class="header-anchor" href="#一、-天下苦rnn久矣-传统门派的死局" aria-label="Permalink to &quot;一、 天下苦RNN久矣：传统门派的死局&quot;">​</a></h3>',9)),(o(),a(i,null,{default:r(()=>[l(n,{id:"mermaid-27",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20subgraph%20RNN%E5%8D%95%E8%A1%8C%E9%81%93%0A%20%20%20%20A1(%E6%88%91)%20--%3E%20B1(%E7%88%B1)%20--%3E%20C1(%E5%90%83)%20--%3E%20D1(%E8%82%89)%0A%20%20%20%20end%0A%20%20%20%20subgraph%20Transformer%E5%A4%9A%E8%BD%A6%E9%81%93%0A%20%20%20%20A2(%E6%88%91)%20--%3E%20O((%E5%90%8C%E6%97%B6%E5%A4%84%E7%90%86))%0A%20%20%20%20B2(%E7%88%B1)%20--%3E%20O%0A%20%20%20%20C2(%E5%90%83)%20--%3E%20O%0A%20%20%20%20D2(%E8%82%89)%20--%3E%20O%0A%20%20%20%20end%0A%20%20%20%20style%20O%20fill%3A%23f9f%2Cstroke%3A%23333%2Cstroke-width%3A2px%0A"})]),fallback:r(()=>[...t[0]||(t[0]=[s(" Loading... ",-1)])]),_:1})),t[4]||(t[4]=e('<p>在Transformer横空出世之前，自然语言处理（NLP）圈子是被RNN（循环神经网络）和它的升级版LSTM统治的。</p><p>RNN的修炼逻辑很像我们人类看书：<strong>逐字阅读</strong>。 比如读“我、爱、吃、烤、肉”这句话，RNN必须先看“我”，再看“爱”，依次看下去。</p><p>这种机制有两个致命的缺陷：</p><ol><li><strong>极其健忘</strong>：当句子特别长的时候，RNN读到最后，往往已经忘了开头是什么。就像你做英语阅读理解，看到最后一段，前面主角叫啥都忘了。</li><li><strong>无法并发（慢得令人发指）</strong>：因为必须等前一个字处理完，才能处理下一个字，这导致现代GPU强大的“多核并行计算”能力完全发挥不出来。GPU就像是拥有几万个打工人的超级工厂，但RNN的机制硬生生把工厂逼成了“单行道”，几万个打工人只能看着一个人干活。</li></ol><p>面对这个死局，谷歌的大神们拍案而起：<strong>既然按顺序读这么慢，那我们干脆把顺序扔掉，让所有的字同时出场！</strong></p><hr><h3 id="二、-降维打击-self-attention-自注意力机制" tabindex="-1">二、 降维打击：Self-Attention（自注意力机制） <a class="header-anchor" href="#二、-降维打击-self-attention-自注意力机制" aria-label="Permalink to &quot;二、 降维打击：Self-Attention（自注意力机制）&quot;">​</a></h3>',7)),(o(),a(i,null,{default:r(()=>[l(n,{id:"mermaid-56",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20IT%5Bit%20%E5%AE%83%5D%20--%3E%7C%E5%8C%B9%E9%85%8D%E5%BA%A6%2080%25%7C%20ANIMAL%5Banimal%20%E5%8A%A8%E7%89%A9%5D%0A%20%20%20%20IT%20--%3E%7C%E5%8C%B9%E9%85%8D%E5%BA%A6%2010%25%7C%20STREET%5Bstreet%20%E9%A9%AC%E8%B7%AF%5D%0A%20%20%20%20IT%20--%3E%7C%E5%8C%B9%E9%85%8D%E5%BA%A6%2010%25%7C%20CROSS%5Bcross%20%E8%BF%87%5D%0A%20%20%20%20ANIMAL%20--%3E%7C%E5%8F%8D%E5%90%91%E5%90%B8%E6%94%B6%E5%90%AB%E4%B9%89%7C%20IT_NEW%5B%E8%BF%9B%E5%8C%96%E7%9A%84%20it%3A%20%E5%8C%85%E5%90%AB%E5%8A%A8%E7%89%A9%E5%B1%9E%E6%80%A7%5D%0A%20%20%20%20style%20IT_NEW%20fill%3A%23dfd%2Cstroke%3A%23333%2Cstroke-width%3A2px%0A"})]),fallback:r(()=>[...t[1]||(t[1]=[s(" Loading... ",-1)])]),_:1})),t[5]||(t[5]=e('<p>把所有的字同时扔进网络，问题就来了：<strong>AI怎么知道字与字之间的关系呢？</strong></p><p>这就引出了Transformer的核心大招——<strong>Self-Attention（自注意力机制）</strong>。</p><p>举个经典的例子：</p><blockquote><p>&quot;The animal didn&#39;t cross the street because <strong>it</strong> was too tired.&quot; （那只动物没有过马路，因为<strong>它</strong>太累了。）</p></blockquote><p>作为人类，我们瞬间就能知道这里的“它（it）”指的是“动物（animal）”而不是“马路（street）”，因为“累”这个属性只属于动物。</p><p>但机器不知道啊！在机器眼里，“它”只是一串冰冷的数字。</p><p><strong>Self-Attention是怎么做的呢？</strong> 它让句子里的<strong>每一个字，都去和其他所有的字“相亲”</strong>，计算一下彼此的“匹配度（注意力分数）”。</p><p>当计算到“it”的时候，它会去环顾四周：</p><ul><li>看看“street”，匹配度10%</li><li>看看“cross”，匹配度20%</li><li>看看“animal”，确认过眼神，是那个对的词！匹配度80%！</li></ul><p>于是，“it”这个词在进入下一层网络时，就会疯狂吸收“animal”的含义。经过这一波操作，原本孤立的单词，就拥有了“全局视野”和“上下文语境”。</p><hr><h3 id="三、-qkv矩阵-相亲市场的降维解释" tabindex="-1">三、 QKV矩阵：相亲市场的降维解释 <a class="header-anchor" href="#三、-qkv矩阵-相亲市场的降维解释" aria-label="Permalink to &quot;三、 QKV矩阵：相亲市场的降维解释&quot;">​</a></h3><p>看到这里，你肯定要问：<strong>那这个“匹配度”到底是怎么算出来的？</strong></p><p>前方高能，全场最核心的硬核知识点来了！别滑走，我保证用最白话的方式让你秒懂。</p><p>为了实现Self-Attention，Transformer为每个字都准备了三个分身（通过三个权重矩阵相乘得到），它们分别是：</p><ul><li><strong>Q（Query，查询）</strong></li><li><strong>K（Key，键）</strong></li><li><strong>V（Value，值）</strong></li></ul><p>这个QKV机制，简直就是一场<strong>大型相亲交友大会</strong>。</p><p>假设你就是句子中的“it”这个词，你来到了相亲现场：</p><p><strong>第一步：亮出你的Q（Query，你想找什么样的人）</strong> 你举起一块牌子，上面写着你的寻偶诉求：“我是个代词，我想找一个名词，最好是活的，能感觉到累的。”（这就是你的Q向量）。</p><p><strong>第二步：看别人的K（Key，别人是什么样的人）</strong> 相亲现场的其他词，每个人胸前都挂着一个名牌（这就是K向量）。 “street”的名牌写着：“我是个名词，我是个无生命的建筑物。” “animal”的名牌写着：“我是个名词，我是个活着的生物。”</p><p><strong>第三步：Q和K配对（计算注意力分数）</strong> 你拿着你的牌子（Q），挨个去和全场其他人的名牌（K）做对比（数学上叫<strong>点乘</strong>）。 你发现自己和“street”毫无火花，但和“animal”的匹配度简直爆表！</p><p><strong>第四步：提取对方的V（Value，对方的内在价值）</strong> 找到了高分匹配对象后，你要怎么做？当然是吸收对方的精华！ 每个人除了名牌，还有一个背包，里面装着他们真正的内在价值（这就是V向量）。 你根据刚才算出的匹配度，按比例拿走大家的V。你拿走了“animal” 80%的V，拿走了“street” 10%的V。</p><p>最后，你把这些拿来的V全部加到自己身上。 恭喜你，你升级了！你不再是那个干瘪的代词“it”，你变成了一个包含了“动物”概念的超级大词！</p><p>这就是QKV矩阵的本质：<strong>通过Q和K的匹配度，来决定我要吸收多少你的V。</strong></p><hr><h3 id="四、-一点点数学-保证不秃头" tabindex="-1">四、 一点点数学，保证不秃头 <a class="header-anchor" href="#四、-一点点数学-保证不秃头" aria-label="Permalink to &quot;四、 一点点数学，保证不秃头&quot;">​</a></h3>',26)),(o(),a(i,null,{default:r(()=>[l(n,{id:"mermaid-161",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20Q%5BQuery%20%E5%AF%BB%E5%81%B6%E8%AF%89%E6%B1%82%5D%20--%3E%20Dot%5B%E7%82%B9%E4%B9%98%E8%AE%A1%E7%AE%97%20Q%20*%20K%5D%0A%20%20%20%20K%5BKey%20%E4%B8%AA%E4%BA%BA%E5%90%8D%E7%89%8C%5D%20--%3E%20Dot%0A%20%20%20%20Dot%20--%3E%20Scale%5B%E9%99%A4%E4%BB%A5%E6%A0%B9%E5%8F%B7dk%20%E9%99%8D%E6%B8%A9%5D%0A%20%20%20%20Scale%20--%3E%20Softmax%5BSoftmax%20%E7%99%BE%E5%88%86%E6%AF%94%E5%8C%96%5D%0A%20%20%20%20Softmax%20--%3E%20Mul%5B%E4%B9%98%E4%BB%A5%20Value%5D%0A%20%20%20%20V%5BValue%20%E5%86%85%E5%9C%A8%E4%BB%B7%E5%80%BC%5D%20--%3E%20Mul%0A%20%20%20%20Mul%20--%3E%20Out%5B%E8%BF%9B%E9%98%B6%E5%90%8E%E7%9A%84%E8%AF%8D%E5%90%91%E9%87%8F%5D%0A%20%20%20%20style%20Softmax%20fill%3A%23bbf%2Cstroke%3A%23333%0A"})]),fallback:r(()=>[...t[2]||(t[2]=[s(" Loading... ",-1)])]),_:1})),t[6]||(t[6]=e('<p>为了让这篇硬核文章功德圆满，我们把上面的相亲过程写成著名的Transformer核心公式。放心，非常优雅：</p><blockquote><p><strong>Attention(Q, K, V) = Softmax( Q * K^T / sqrt(d_k) ) * V</strong></p></blockquote><p>我们拆解一下，简直像呼吸一样自然：</p><ol><li><strong>Q * K^T</strong>：这就是你拿着牌子看别人名牌的过程（点乘计算匹配度）。</li><li><strong>/ sqrt(d_k)</strong>：为什么要除以一个根号下d_k（维度大小）？因为如果匹配度数值太大，相亲现场就容易“上头”（梯度消失）。除以这个数，相当于给现场降降温，让大家保持理智。</li><li><strong>Softmax</strong>：这是一个归一化函数。简单来说，就是把所有的匹配度变成百分比，保证所有人加起来等于100%（比如80%给animal，10%给street）。</li><li><strong>最后乘上 V</strong>：根据算出的百分比，拿走对应的内在价值，打包带走。</li></ol><p>完美闭环！你看，顶级AI的底层数学逻辑，就是这么朴实无华。</p><hr><h3 id="五、-结语与预告" tabindex="-1">五、 结语与预告 <a class="header-anchor" href="#五、-结语与预告" aria-label="Permalink to &quot;五、 结语与预告&quot;">​</a></h3><p>通过抛弃RNN的顺序结构，引入QKV的Self-Attention机制，Transformer实现了两大逆天神迹：</p><ol><li><strong>拥有了上帝视角</strong>：无论句子多长，距离多远的词，只要匹配度高，瞬间就能建立联系。</li><li><strong>极速狂飙</strong>：所有词语的相亲过程是<strong>同时进行</strong>的！GPU终于可以满血输出了，这为后来动辄千亿参数的大模型训练打下了最坚实的算力基础。</li></ol><p>但是，细心的你可能发现了盲点： 既然所有的词是同时出场的，那“我打你”和“你打我”，在Transformer眼里岂不是一模一样？机器怎么知道词语的先后顺序呢？ 另外，一个词可能在不同维度上有不同的含义（比如又想找名词，又想找形容词），一次相亲够用吗？</p><p>这就是我们要留到下一篇填的坑了： <strong>AI大模型修仙传（五）：Transformer下篇——多头注意力（Multi-Head）与位置编码（Positional Encoding）的绝对防御。</strong></p><p>点赞转发收藏三连，我们下期修仙界再见！</p>',12))])}const C=A(g,[["render",d]]);export{h as __pageData,C as default};
